{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Cerivastatin, a statin sharing the same 3,5-dihydroxyhept-6-enoic acid side chain and a fluorophenyl substituent, has an absolute oral bioavailability of about 60% in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Trovafloxacin, a fluoroquinolone with a fluorophenyl-substituted heteroaromatic core and carboxylic acid, has an absolute oral bioavailability of 88% in humans after a 200 mg dose, supporting high oral absorption for the query's similar aromatic/acid features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Ketanserin, which contains a fluorophenyl ketone and piperidine, has an absolute bioavailability around 49% in young volunteers, providing additional evidence that fluorophenyl-containing drug-like scaffolds can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Paltusotine, a structurally distinct oral drug, had 69% absolute bioavailability in a phase 1 IV-microtracer study, reinforcing that high oral bioavailability is achievable for complex drug-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Propranolol absolute bioavailability in normal volunteers was 15.8%, below the threshold, but this reflects extensive first-pass hepatic extraction of an aryloxypropanolamine and is not mechanistically transferable to the statin-like carboxylic acid query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a pitavastatin-like statin with a dihydroxyheptenoic acid side chain. The closest analogue cerivastatin has ~60% absolute oral bioavailability, and multiple other high-transfer molecules (trovafloxacin 88%, ketanserin ~50%, paltusotine 69%) support F ≥ 20%. The only sub-20% evidence (propranolol) is mechanistically tied to high first-pass metabolism of a different scaffold and is outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the exact query molecule; reliance on close analogue cerivastatin and other high-F molecules.",
    "Propranolol low-F records are mechanistically mismatched; no query-specific first-pass metabolism data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

